import math

def is_prime(n):
    """Checks if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    """Checks if n is a perfect cube and returns its integer cube root if it is."""
    if n < 0:
        return None  # We only deal with positive N here

    # Estimate the cube root using floating point math
    root_approx = round(n**(1/3))

    # Check the approximation and its neighbors to ensure accuracy due to float precision
    for p in range(max(1, root_approx - 2), root_approx + 3):
        if p**3 == n:
            return p
    return None

# 1. Generate primes up to 100
primes = [i for i in range(2, 101) if is_prime(i)]

results = []

print("Testing primes q <= 100...")
for q in primes:
    # 2. Calculate N = q^2 - q + 1
    N = q*q - q + 1

    # 3. Check if N is a perfect cube
    p = is_perfect_cube(N)

    if p is not None:
        # 4. Verify that the cube root p is a prime number and that p != q
        if is_prime(p) and p != q:
            results.append((q, p, N))

print("\n--- Results ---")
if results:
    print("Found pairs (q, p, N):")
    for q, p, N in results:
        print(f"q={q}, p={p}, N={N}")
else:
    print("No pairs found.")

# Format results for note writing
