import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_perfect_cube(n):
    if n < 0:
        return False
    # Using round(n**(1/3)) to handle potential floating point inaccuracies near integers
    root = round(n**(1/3))
    return root**3 == n, root

# Generate primes up to 500
primes = []
for num in range(2, 501):
    if is_prime(num):
        primes.append(num)

# Filter for q such that 100 < q <= 500
q_candidates = [q for q in primes if q > 100]

results = []
for q in q_candidates:
    N = q*q - q + 1

    is_cube, p = is_perfect_cube(N)

    if is_cube:
        # Check if p is prime and p != q
        if is_prime(p) and p != q:
            results.append((q, p, N))

print("Found pairs (q, p, N) for 100 < q <= 500:")
if results:
    for q, p, N in results:
        print(f"(q={q}, p={p}, N={N})")
else:
    print("No new pairs found in the range 100 < q <= 500.")
